"""Design sheets from real Godot turnaround captures; editable SVG with embedded images."""
from pathlib import Path
import base64,html
r=Path(__file__).resolve().parents[1]; out=r/'docs/ac1/assets/final';out.mkdir(parents=True,exist_ok=True)
def text(x,y,t,size=22,c='#f2e8ce'):return f'<text x="{x}" y="{y}" fill="{c}" font-family="Arial,sans-serif" font-size="{size}">{html.escape(t)}</text>'
def image(path,x,y,w,h):
 data=base64.b64encode(path.read_bytes()).decode();return f'<image x="{x}" y="{y}" width="{w}" height="{h}" href="data:image/png;base64,{data}"/>'
def sheet(name,title,subtitle,views,notes):
 s=['<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1600" height="1000" viewBox="0 0 1600 1000">','<rect width="1600" height="1000" fill="#102b2a"/>',text(50,50,'INITY PIXEL  /  DIREÇÃO VISUAL AC1  /  30.09.2026',18,'#69be9b'),text(50,111,title,44),text(50,150,subtitle,20,'#c1d5c9')]
 for i,(label,file) in enumerate(views):
  x=50+i*505;s+=[f'<rect x="{x}" y="187" width="480" height="580" rx="16" fill="#173a35"/>',text(x+24,231,label,20,'#e7ae58'),f'<defs><clipPath id="c{i}"><rect x="{x+10}" y="245" width="460" height="510"/></clipPath></defs>',f'<g clip-path="url(#c{i})">',image(r/'docs/ac1/evidence'/file,x-240,244,960,540),'</g>']
 for i,n in enumerate(notes):s.append(text(50,818+i*31,n,21))
 for i,c in enumerate(['#102b2a','#24554a','#69be9b','#e7ae58','#c76c4c','#f2e8ce']):s+=[f'<rect x="{1100+i*72}" y="838" width="54" height="54" rx="8" fill="{c}"/>']
 s.append(text(50,966,'Modelo 3D implementado • Proposta artística sujeita à aprovação do grupo • Fontes: scenes/visuals + tools/build_visuals.py',17,'#a7c6b6'));s.append('</svg>');(out/name).write_text('\n'.join(s))
sheet('guardiao.svg','Guardião do refúgio','Três vistas ortográficas do modelo integrado — referência de proporção, acessórios e materiais.', [('FRENTE','guardian_frente.png'),('LATERAL','guardian_lateral.png'),('COSTAS','guardian_costas.png')],['Proporção: aproximadamente 4 cabeças; altura visual ≈ 2 m. Colisão preservada: cápsula de 1,8 m.','Túnica âmbar e lenço jade: silhueta legível contra a floresta. Bolsa lateral, botas e machado curto.','Materiais foscos: tecido, couro, pedra e madeira. Caminhada e golpe animados por pivôs.'])
sheet('dinossauros.svg','Uma criatura, três leituras','O vínculo é visível no colar e na crista. A variante tem chifres e não aceita domesticação.', [('SELVAGEM • CORAL','dino_lateral.png'),('ALIADO • COLAR JADE','dino_aliado.png'),('CARNOTAURO • CHIFRES','carno_lateral.png')],['Silhueta bípede: focinho, cauda longa, pernas fortes, pequenas garras e crista.','Selvagem: 80 HP. Aliado mantém os HP restantes; aparência não concede cura nem bônus.','Carnotauro: variante não domesticável. Nome e direção visual ainda provisórios.'])
s=['<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1150" viewBox="0 0 1600 1150"><rect width="1600" height="1150" fill="#102b2a"/>',text(45,50,'INITY PIXEL / CLAREIRA DO REFÚGIO',20,'#69be9b'),text(45,110,'Dia para preparar. Noite para defender.',44),text(45,150,'Estudo de iluminação baseado no cenário efetivamente integrado na Godot.',22)]
for i,(name,file) in enumerate([('DIA • âmbar, musgo e pedra','arena_dia.png'),('NOITE • azul frio e luz do refúgio','arena_noite.png')]):
 y=180+i*435;s+=[text(45,y+27,name,22,'#e7ae58'),image(r/'docs/ac1/evidence'/file,45,y+40,740,416)]
s+=[text(850,265,'ARENA 40 × 40 m',29,'#e7ae58'),text(850,320,'Base (0, −15) • Guardião (0, 0)'),text(850,365,'Onda (0, +15) • Posto (0, −7)'),text(850,410,'Encontro territorial (−10, +5)'),text(850,485,'Corredor livre de colisores: 10 m.'),text(850,530,'Caminho central de terra: 8 m.'),text(850,575,'Decoração lateral sem bloquear a IA.'),text(850,650,'Pedras, árvores, samambaias e arco.'),text(850,695,'Limites físicos nas quatro bordas.'),text(850,740,'Rochas distantes compõem o horizonte.'),text(850,830,'Base: pedra, estandartes e cristal âmbar.'),text(850,875,'Proposta fantástica, sem precisão histórica.'),text(45,1120,'Capturas reais do protótipo • Câmera de apresentação • Arte final depende da revisão humana do grupo.',19,'#a7c6b6'),'</svg>'];(out/'cenario_dia_noite.svg').write_text('\n'.join(s))
# Identity sheet uses editable typography and the new pixel-mark motif.
s=['<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900"><rect width="1600" height="900" fill="#102b2a"/>',text(60,60,'ESTÚDIO INITY PIXEL / IDENTIDADE 02',20,'#69be9b'),text(60,155,'A clareira tem uma nova defesa.',54),'<g transform="translate(60 245) scale(2)"><path fill="#69be9b" d="M8 12h20v12H20v16h8v12H8zM36 12h20v40H36V40h8V24h-8z"/><path fill="#e7ae58" d="m32 21 10 11-10 11-10-11z"/></g>',text(225,316,'INITY PIXEL',62),text(790,255,'JOGO',24,'#69be9b'),text(790,332,'INFINITY',64),text(790,412,'PIXEL',64),text(790,455,'DOMESTIQUE. POSICIONE. DEFENDA.',22,'#e7ae58'),text(60,514,'Símbolo: duas formas de pixel protegem um núcleo de cristal.',24),text(60,557,'Assinatura tipográfica: sans-serif, títulos claros, acentos em âmbar e jade.',24),text(60,610,'Nome do jogo atualizado; identidade e monetização aguardam revisão do grupo.',24)]
for i,c in enumerate(['#102b2a','#24554a','#69be9b','#e7ae58','#c76c4c','#f2e8ce']):s+=[f'<rect x="{60+i*235}" y="672" width="208" height="100" fill="{c}" stroke="#647d6e"/>',text(60+i*235,810,c,23)]
s+=['</svg>'];(out/'identidade.svg').write_text('\n'.join(s))
print('4 pranchas SVG criadas em',out)
